<?php
namespace App\Services;
use App\Models\Asset;use App\Models\AssetDisposal;use App\Models\AssetMaintenance;use App\Models\User;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class AssetDisposalService{
private function ensureEligible(Asset $asset):void{if($asset->status==='dihapus')throw ValidationException::withMessages(['asset_id'=>'Aset sudah berstatus dihapus.']);if($asset->loans()->whereNull('returned_at')->exists()||$asset->status==='dipinjam')throw ValidationException::withMessages(['asset_id'=>'Aset masih dalam proses peminjaman dan belum dapat dihapus.']);if($asset->maintenances()->whereIn('maintenance_status',AssetMaintenance::ACTIVE_STATUSES)->exists()||$asset->status==='perawatan')throw ValidationException::withMessages(['asset_id'=>'Aset masih dalam proses perawatan dan belum dapat dihapus.']);}
public function create(array $data,User $user):AssetDisposal{return DB::transaction(function()use($data,$user){$asset=Asset::lockForUpdate()->findOrFail($data['asset_id']);$this->ensureEligible($asset);if(AssetDisposal::where('asset_id',$asset->id)->where('status','diajukan')->exists())throw ValidationException::withMessages(['asset_id'=>'Aset sudah memiliki pengajuan penghapusan yang menunggu persetujuan.']);return AssetDisposal::create([...$data,'condition_at_disposal'=>$asset->condition,'created_by'=>$user->id,'status'=>'diajukan']);});}
public function approve(AssetDisposal $disposal,User $user):void{DB::transaction(function()use($disposal,$user){$locked=AssetDisposal::lockForUpdate()->findOrFail($disposal->id);if($locked->status!=='diajukan')throw ValidationException::withMessages(['disposal'=>'Pengajuan ini sudah diproses.']);$asset=Asset::lockForUpdate()->findOrFail($locked->asset_id);$this->ensureEligible($asset);$locked->update(['status'=>'disetujui','approved_by'=>$user->id,'approved_at'=>now(),'rejection_reason'=>null]);$asset->update(['status'=>'dihapus']);});}
public function reject(AssetDisposal $disposal,array $data,User $user):void{DB::transaction(function()use($disposal,$data,$user){$locked=AssetDisposal::lockForUpdate()->findOrFail($disposal->id);if($locked->status!=='diajukan')throw ValidationException::withMessages(['disposal'=>'Pengajuan ini sudah diproses.']);$locked->update(['status'=>'ditolak','rejection_reason'=>$data['rejection_reason'],'approved_by'=>$user->id,'approved_at'=>now()]);});}}
